// Logo do canal Explicando F1 (redondo), embutido para carregar sem pasta pública (o render usa a pasta do vídeo).
// Fonte: logo_canal.jpeg (cópia de Downloads\logof1.jpeg, 2026-11-12). Usado na Sphere de Las Vegas (cenario.ts).
import * as THREE from "three";
import { continueRender, delayRender } from "remotion";

const DADOS = "data:image/jpeg;base64,";

let img: HTMLImageElement | null = null;
let pronto: Promise<void> | null = null;
let tex: THREE.CanvasTexture | null = null;
let canvas: HTMLCanvasElement | null = null;

/** Promessa de quando a imagem do logo está decodificada. */
export function logoPronto(): Promise<void> {
  if (!pronto) {
    img = new Image();
    img.src = DADOS;
    pronto = img.decode().catch(() => undefined);
  }
  return pronto;
}

// segura o render do Remotion até o logo decodificar (em qualquer composição que importe este módulo)
if (typeof window !== "undefined") {
  const alca = delayRender("logo do canal");
  void logoPronto().then(() => {
    desenharDisco();
    continueRender(alca);
  });
}

/** Recorta o logo num DISCO perfeito (fora do círculo = transparente; Felipe, 2026-11-12: "bordas quadradas"),
 *  com um aro vermelho fino na borda. O círculo do logo ocupa ~93% da largura da imagem. */
function desenharDisco() {
  if (!img || !img.naturalWidth) return;
  canvas ??= document.createElement("canvas");
  const L = 1024;
  canvas.width = canvas.height = L;
  const x = canvas.getContext("2d")!;
  x.clearRect(0, 0, L, L);
  const r = L * 0.465;
  x.save();
  x.beginPath();
  x.arc(L / 2, L / 2, r, 0, Math.PI * 2);
  x.clip();
  x.drawImage(img, 0, 0, L, L);
  x.restore();
  x.beginPath();
  x.arc(L / 2, L / 2, r - 4, 0, Math.PI * 2);
  x.lineWidth = 8;
  x.strokeStyle = "#e10600";
  x.stroke();
  if (tex) tex.needsUpdate = true;
}

export const logoCarregado = () => !!img && img.complete && img.naturalWidth > 0;

/** Textura do logo em disco (fundo transparente), uma só para o vídeo inteiro. */
export function texturaLogo(): THREE.Texture {
  if (tex) return tex;
  void logoPronto();
  canvas ??= document.createElement("canvas");
  if (logoCarregado()) desenharDisco();
  tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  tex.wrapS = tex.wrapT = THREE.ClampToEdgeWrapping;
  return tex;
}